INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q17070460', 'Siege of Mombasa', 'The siege of Mombasa was an attack on the Portuguese city of Mombasa and Fort Jesus by the army of the Ya''rubid ruler of Oman, Saif I bin Sultan, from 13 March 1696 to 13 December 1698.', 1696, 3, 13, 1698, 12, 13, 'day', '13 March 1696 – 13 December 1698', 37, 'https://en.wikipedia.org/wiki/Siege_of_Mombasa_(1696%E2%80%931698)'),
  ('Q16932084', 'Lari Massacre', 'The Lari massacre was an incident during the Mau Mau Uprising in which the Mau Mau massacred approximately 74 people, including some members of the loyalist Home Guard, but mostly their families: women, children and elderly relatives. Those murdered included prominent local loyalist Luka Kahangara.', 1953, 3, 26, NULL, NULL, NULL, 'day', '26 March 1953', 41, 'https://en.wikipedia.org/wiki/Lari_massacre'),
  ('Q1271059', 'Shifta War', 'The Shifta War or Gaf Daba (1963–1967) was a secessionist conflict in which ethnic Somalis, Muslim Borana, Sakuye, Gabbra and Rendille in the then Northern Frontier District (NFD) of Kenya attempted to join Somalia. The Kenyan government named the conflict "shifta", after the Swahili word for "bandit", as part of a propaganda effort.', 1963, NULL, NULL, 1967, NULL, NULL, 'year', '1963–1967', 47, 'https://en.wikipedia.org/wiki/Shifta_War'),
  ('Q534358', 'Lufthansa Flight 540', 'Lufthansa Flight 540 was a scheduled commercial flight for Lufthansa, serving the Frankfurt–Nairobi–Johannesburg route. On 20 November 1974, the Boeing 747-130 that was operating as Flight 540 was carrying 157 people (139 passengers and 18 crew members) crashed and caught fire shortly after taking off from Embakasi Airport in Nairobi, Kenya, for the last leg of the flight, resulting in the deaths of 54 passengers and 5 crew members.', 1974, 11, 20, NULL, NULL, NULL, 'day', '20 November 1974', 51, 'https://en.wikipedia.org/wiki/Lufthansa_Flight_540'),
  ('Q130754', '2004 Indian Ocean earthquake', 'On 26 December 2004, at 07:58:53 local time (UTC+7), a Mw 9.2–9.3 earthquake struck with its epicenter off the west coast of Aceh, in northern Sumatra, Indonesia. The undersea megathrust earthquake, known in the scientific community as the Sumatra–Andaman earthquake, was caused by a rupture along the fault boundary between the Burma plate and the Indian plate, and reached a maximum Mercalli intensity of IX in some areas.', 2004, 12, 26, NULL, NULL, NULL, 'day', '26 December 2004', 85, 'https://en.wikipedia.org/wiki/2004_Indian_Ocean_earthquake_and_tsunami'),
  ('Q166087', '2007–08 Kenyan crisis', 'The 2007–2008 Kenyan crisis was a violent political, economic, and humanitarian crisis in Kenya. The crisis erupted after incumbent President Mwai Kibaki was declared the winner of the 2007 presidential election.', 2007, 12, 27, 2008, 2, 28, 'day', '27 December 2007 – 28 February 2008', 56, 'https://en.wikipedia.org/wiki/2007%E2%80%932008_Kenyan_crisis'),
  ('Q14941568', 'Westgate shopping mall shooting', 'On 21 September 2013, four gunmen attacked the Westgate shopping mall, an upmarket mall in Nairobi, Kenya. There are conflicting reports about the number killed in the attack, since part of the mall collapsed due to a fire that started during the siege.', 2013, 9, NULL, 2013, 9, 24, 'month', 'September 2013 – 24 September 2013', 67, 'https://en.wikipedia.org/wiki/Westgate_shopping_mall_attack'),
  ('Q19750438', 'Garissa University College attack', 'On 2 April 2015, gunmen stormed the Garissa University College in Garissa, Kenya, killing 148 people, and injuring at least 79. The militant groups Al-Qaeda and Al-Shabaab, which the gunmen claimed to belong to, took responsibility for the attack.', 2015, 4, 2, NULL, NULL, NULL, 'day', '2 April 2015', 63, 'https://en.wikipedia.org/wiki/Garissa_University_College_attack'),
  ('Q60628970', '2019 Nairobi attack', 'On January 15, 2019, a coordinated attack perpetrated by Al-Shabaab occurred at the DusitD2 complex in Westlands District, Nairobi, Kenya. The attack began at around 14:30 EAT (UTC+3), shortly after a suicide bomber blew himself up near the centre of the complex at a restaurant.', 2019, 1, 15, NULL, NULL, NULL, 'day', '15 January 2019', 56, 'https://en.wikipedia.org/wiki/Nairobi_DusitD2_complex_attack'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q118316106', '2023 Africa floods', 'From February to late-December 2023, floods killed over 2,600 people in 15 countries across Africa.', 2023, 2, 5, NULL, NULL, NULL, 'day', '5 February 2023', 43, 'https://en.wikipedia.org/wiki/2023_Africa_floods'),
  ('Q125924337', '2024 Mai Mahiu flash flood', 'On 29 April 2024, a blockage in a culvert beneath a railway embankment led to a catastrophic failure and inundation in Kenya, killing at least 50 people. The event was initially described as a ''dam failure''.', 2024, 4, 29, NULL, NULL, NULL, 'day', '29 April 2024', 34, 'https://en.wikipedia.org/wiki/2024_Mai_Mahiu_flash_flood'),
  ('Q126906449', 'Kenya Finance Bill protests', 'A series of decentralized mass protests took place in Kenya in response to tax increases proposed by the Government of Kenya in the Finance Bill 2024. Following the storming of the Kenyan Parliament, president William Ruto reportedly rejected the Bill on 28 June; signed into law the "Appropriations Bill 2024" to address the budget shortfall caused by the rejection.', 2024, 6, 18, 2024, 8, 8, 'day', '18 June 2024 – 8 August 2024', 45, 'https://en.wikipedia.org/wiki/Kenya_Finance_Bill_protests'),
  ('Q138637932', '2026 Kenya floods', 'Between early March and late May 2026, flash flooding caused by heavy rainfall affected parts of Kenya, particularly the capital, Nairobi, killing at least 66 people. Floodwaters inundated roads across the city after intense overnight rainfall caused rivers to overflow, sweeping away vehicles and stranding motorists.', 2026, NULL, NULL, NULL, NULL, NULL, 'year', '2026', 43, 'https://en.wikipedia.org/wiki/2026_Kenya_floods');
